import{_ as e,W as a,X as n,a2 as s}from"./framework-6a3aa88c.js";const i={},d=s(`<h1 id="第三课-看懂第一份-kubernetes-yaml" tabindex="-1"><a class="header-anchor" href="#第三课-看懂第一份-kubernetes-yaml" aria-hidden="true">#</a> 第三课：看懂第一份 Kubernetes YAML</h1><h2 id="这节课只解决一个问题" tabindex="-1"><a class="header-anchor" href="#这节课只解决一个问题" aria-hidden="true">#</a> 这节课只解决一个问题</h2><p>上一课使用下面的命令创建了 Nginx：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl apply <span class="token parameter variable">-f</span> labs/02-第一个应用/01-nginx-pod.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这一课不增加新应用，只解释 Kubernetes 怎样读懂这个文件。</p><p>学完后，再看到一份简单 YAML，你应该能判断：</p><ul><li>要创建什么；</li><li>对象叫什么；</li><li>要运行什么容器；</li><li>哪些内容是我们写的，哪些是 Kubernetes 后来补充的。</li></ul><h2 id="一、先理解-yaml-的三个书写规则" tabindex="-1"><a class="header-anchor" href="#一、先理解-yaml-的三个书写规则" aria-hidden="true">#</a> 一、先理解 YAML 的三个书写规则</h2><p>YAML 是一种用于表达结构化数据的文本格式。它不属于 Kubernetes，很多其他软件也使用 YAML。</p><h3 id="规则-1-缩进表示所属关系" tabindex="-1"><a class="header-anchor" href="#规则-1-缩进表示所属关系" aria-hidden="true">#</a> 规则 1：缩进表示所属关系</h3><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">metadata</span><span class="token punctuation">:</span>
  <span class="token key atrule">name</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall<span class="token punctuation">-</span>web<span class="token punctuation">-</span>preview
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>name</code> 前面有两个空格，表示它属于 <code>metadata</code>。</p><p>可以画成：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>metadata
└── name
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>缩进层级必须对齐，通常使用空格，不使用 Tab。</p><h3 id="规则-2-冒号表示-名称对应一个值" tabindex="-1"><a class="header-anchor" href="#规则-2-冒号表示-名称对应一个值" aria-hidden="true">#</a> 规则 2：冒号表示“名称对应一个值”</h3><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">kind</span><span class="token punctuation">:</span> Pod
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>可以读作：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>kind 的值是 Pod
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="规则-3-短横线表示列表中的一项" tabindex="-1"><a class="header-anchor" href="#规则-3-短横线表示列表中的一项" aria-hidden="true">#</a> 规则 3：短横线表示列表中的一项</h3><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">containers</span><span class="token punctuation">:</span>
  <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> nginx
    <span class="token key atrule">image</span><span class="token punctuation">:</span> nginx<span class="token punctuation">:</span><span class="token number">1.27</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>containers</code> 是容器列表，短横线表示列表中的一个容器。</p><p>画成：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>containers
└── 第 1 个容器
    ├── name: nginx
    └── image: nginx:1.27
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>以后一个 Pod 中有多个容器时，会出现多个短横线。现在只有一个。</p><h2 id="二、把文件分成四大块" tabindex="-1"><a class="header-anchor" href="#二、把文件分成四大块" aria-hidden="true">#</a> 二、把文件分成四大块</h2><p>打开 <code>labs/02-第一个应用/01-nginx-pod.yaml</code>：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">apiVersion</span><span class="token punctuation">:</span> v1
<span class="token key atrule">kind</span><span class="token punctuation">:</span> Pod
<span class="token key atrule">metadata</span><span class="token punctuation">:</span>
  <span class="token key atrule">name</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall<span class="token punctuation">-</span>web<span class="token punctuation">-</span>preview
<span class="token key atrule">spec</span><span class="token punctuation">:</span>
  <span class="token key atrule">containers</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> nginx
      <span class="token key atrule">image</span><span class="token punctuation">:</span> nginx<span class="token punctuation">:</span><span class="token number">1.27</span>
      <span class="token key atrule">ports</span><span class="token punctuation">:</span>
        <span class="token punctuation">-</span> <span class="token key atrule">containerPort</span><span class="token punctuation">:</span> <span class="token number">80</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>先不看细节，只看最左边没有缩进的内容：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>apiVersion
kind
metadata
spec
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这就是这份文件的四个顶层部分。</p><h2 id="三、apiversion-按哪一版规则理解" tabindex="-1"><a class="header-anchor" href="#三、apiversion-按哪一版规则理解" aria-hidden="true">#</a> 三、<code>apiVersion</code>：按哪一版规则理解</h2><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">apiVersion</span><span class="token punctuation">:</span> v1
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>白话理解：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>请按照 v1 这版规则解释这个对象。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Kubernetes 的功能会发展，不同对象可能使用不同版本的书写规则。因此 YAML 需要告诉 Kubernetes 应该按哪一版规则解析。</p><p>现在只记住：Pod 通常写 <code>v1</code>。不要把它理解成 Nginx 版本，也不要因为集群版本是 v1.32.2 就改成 <code>v1.32.2</code>。</p><h2 id="四、kind-要创建什么" tabindex="-1"><a class="header-anchor" href="#四、kind-要创建什么" aria-hidden="true">#</a> 四、<code>kind</code>：要创建什么</h2><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">kind</span><span class="token punctuation">:</span> Pod
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>kind</code> 表示对象类型。这里是在告诉 Kubernetes：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>我要创建一个 Pod。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>以后还会见到其他类型：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">kind</span><span class="token punctuation">:</span> Service
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>表示创建 Service；</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">kind</span><span class="token punctuation">:</span> Deployment
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>表示创建 Deployment。</p><p>现在不用学习它们的用途，只要知道 <code>kind</code> 决定“这是什么”。</p><h2 id="五、metadata-它叫什么" tabindex="-1"><a class="header-anchor" href="#五、metadata-它叫什么" aria-hidden="true">#</a> 五、<code>metadata</code>：它叫什么</h2><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">metadata</span><span class="token punctuation">:</span>
  <span class="token key atrule">name</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall<span class="token punctuation">-</span>web<span class="token punctuation">-</span>preview
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>metadata</code> 可以先翻译为“对象的身份信息”。其中：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall<span class="token punctuation">-</span>web<span class="token punctuation">-</span>preview
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>给这个 Pod 起名为 <code>qingyun-mall-web-preview</code>。</p><p>因此上一课才能通过名字查找它：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get pod qingyun-mall-web-preview
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这三部分正好对应：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>get              获取、查看
pod              对象类型
qingyun-mall-web-preview  对象名称
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="六、spec-希望它怎样运行" tabindex="-1"><a class="header-anchor" href="#六、spec-希望它怎样运行" aria-hidden="true">#</a> 六、<code>spec</code>：希望它怎样运行</h2><p><code>spec</code> 是 specification 的缩写，可以理解为“要求”或者“期望配置”。</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">spec</span><span class="token punctuation">:</span>
  <span class="token key atrule">containers</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> nginx
      <span class="token key atrule">image</span><span class="token punctuation">:</span> nginx<span class="token punctuation">:</span><span class="token number">1.27</span>
      <span class="token key atrule">ports</span><span class="token punctuation">:</span>
        <span class="token punctuation">-</span> <span class="token key atrule">containerPort</span><span class="token punctuation">:</span> <span class="token number">80</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这段要求 Kubernetes：</p><ol><li>Pod 中要有一个容器；</li><li>容器名叫 <code>nginx</code>；</li><li>使用 <code>nginx:1.27</code> 镜像；</li><li>容器使用 80 端口。</li></ol><p>关系如下：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Pod: qingyun-mall-web-preview
└── spec：运行要求
    └── containers：容器列表
        └── 容器 nginx
            ├── image: nginx:1.27
            └── containerPort: 80
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意这里有两个名字：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>metadata.name = qingyun-mall-web-preview  → Pod 名字
containers[].name = nginx        → Pod 内的容器名字
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>它们不是同一个层级。一个 Pod 以后可以包含多个容器，所以每个容器也需要自己的名字。</p><h2 id="七、实操-重新创建并观察" tabindex="-1"><a class="header-anchor" href="#七、实操-重新创建并观察" aria-hidden="true">#</a> 七、实操：重新创建并观察</h2><p>进入课程目录：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">cd</span> /Users/qintianpeng/2026/code/k8s
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>创建 Pod：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl apply <span class="token parameter variable">-f</span> labs/02-第一个应用/01-nginx-pod.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>等待它运行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get pod qingyun-mall-web-preview <span class="token parameter variable">-w</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>看到 <code>1/1 Running</code> 后按 <code>Control + C</code>。</p><h2 id="八、观察-kubernetes-补充的-status" tabindex="-1"><a class="header-anchor" href="#八、观察-kubernetes-补充的-status" aria-hidden="true">#</a> 八、观察 Kubernetes 补充的 <code>status</code></h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get pod qingyun-mall-web-preview <span class="token parameter variable">-o</span> yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>-o yaml</code> 表示“以 YAML 格式输出这个 Pod”。</p><p>输出会比原文件长很多。现在不要试图全部看懂，只寻找最左侧的五块：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>apiVersion:
kind:
metadata:
spec:
status:
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>你最初只写了四块，查询结果多了：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">status</span><span class="token punctuation">:</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>status</code> 表示 Kubernetes 观察到的当前状态。里面通常能看到：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">phase</span><span class="token punctuation">:</span> Running
<span class="token key atrule">podIP</span><span class="token punctuation">:</span> 10.x.x.x
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>现在建立一个重要区别：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>spec   = 你希望怎样运行
status = Kubernetes 观察到现在怎样
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>例如：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>spec.image = nginx:1.27  → 你要求使用的镜像
status.phase = Running   → Kubernetes 观察到 Pod 正在运行
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>status</code> 一般不由我们写进创建文件，因为 Pod 还没创建时，它没有实际运行状态和 Pod IP。</p><h2 id="九、为什么查询结果比原文件长" tabindex="-1"><a class="header-anchor" href="#九、为什么查询结果比原文件长" aria-hidden="true">#</a> 九、为什么查询结果比原文件长</h2><p>除了 <code>status</code>，你还会看到很多没有手写的内容，例如创建时间和内部编号。</p><p>这不是 Kubernetes 偷偷修改了本地文件。实际发生的是：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>本地 YAML 文件
   │ kubectl apply
   ▼
Kubernetes 中的对象
   ├── 保留你的要求
   ├── 补充默认设置
   ├── 补充身份信息
   └── 补充运行状态
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>本地文件依旧是原来的简短内容；<code>kubectl get ... -o yaml</code> 展示的是集群中更加完整的对象。</p><h2 id="十、让-kubernetes-解释字段" tabindex="-1"><a class="header-anchor" href="#十、让-kubernetes-解释字段" aria-hidden="true">#</a> 十、让 Kubernetes 解释字段</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl explain pod
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>explain</code> 表示解释。输出虽然是英文，但能看到 Pod 的主要字段：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>apiVersion
kind
metadata
spec
status
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>想查询 <code>spec</code> 是什么：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl explain pod.spec
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这条命令暂时不用读完。它的价值是告诉你：以后遇到陌生字段，可以让当前集群解释，不必全靠记忆。</p><h2 id="十一、清理实验" tabindex="-1"><a class="header-anchor" href="#十一、清理实验" aria-hidden="true">#</a> 十一、清理实验</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl delete <span class="token parameter variable">-f</span> labs/02-第一个应用/01-nginx-pod.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>然后确认：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get pod qingyun-mall-web-preview
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>看到 <code>NotFound</code> 表示清理完成。</p><h2 id="十二、问题与直接回答" tabindex="-1"><a class="header-anchor" href="#十二、问题与直接回答" aria-hidden="true">#</a> 十二、问题与直接回答</h2><h3 id="yaml-是-kubernetes-专用语言吗" tabindex="-1"><a class="header-anchor" href="#yaml-是-kubernetes-专用语言吗" aria-hidden="true">#</a> YAML 是 Kubernetes 专用语言吗？</h3><p>不是。YAML 只是一种表达结构化数据的文本格式，Kubernetes 是它的使用者之一。</p><h3 id="为什么-yaml-的缩进不能随便写" tabindex="-1"><a class="header-anchor" href="#为什么-yaml-的缩进不能随便写" aria-hidden="true">#</a> 为什么 YAML 的缩进不能随便写？</h3><p>因为缩进表示所属关系。缩进错误可能改变字段层级，或者让文件无法解析。</p><h3 id="kind-与-name-有什么区别" tabindex="-1"><a class="header-anchor" href="#kind-与-name-有什么区别" aria-hidden="true">#</a> <code>kind</code> 与 <code>name</code> 有什么区别？</h3><p><code>kind</code> 是对象类型，例如 Pod；<code>name</code> 是这个具体对象的名称，例如 <code>qingyun-mall-web-preview</code>。</p><h3 id="spec-与-status-有什么区别" tabindex="-1"><a class="header-anchor" href="#spec-与-status-有什么区别" aria-hidden="true">#</a> <code>spec</code> 与 <code>status</code> 有什么区别？</h3><p><code>spec</code> 是你提交的运行要求，<code>status</code> 是 Kubernetes 观察到的实际状态。</p><h3 id="为什么原文件没有-status" tabindex="-1"><a class="header-anchor" href="#为什么原文件没有-status" aria-hidden="true">#</a> 为什么原文件没有 <code>status</code>？</h3><p>因为创建前还没有实际运行状态。status 通常由 Kubernetes 在对象运行过程中填写。</p><h3 id="为什么-pod-名和容器名不一样" tabindex="-1"><a class="header-anchor" href="#为什么-pod-名和容器名不一样" aria-hidden="true">#</a> 为什么 Pod 名和容器名不一样？</h3><p>因为它们属于不同层级。Pod 是外层运行单元，里面可以有一个或多个容器，每个容器也需要名称。</p><h2 id="本课只记住五句话" tabindex="-1"><a class="header-anchor" href="#本课只记住五句话" aria-hidden="true">#</a> 本课只记住五句话</h2><ol><li>YAML 用缩进表达所属关系，用短横线表达列表项。</li><li><code>apiVersion</code> 表示按哪版规则理解。</li><li><code>kind</code> 表示对象类型，<code>metadata.name</code> 表示对象名字。</li><li><code>spec</code> 是期望配置，<code>status</code> 是实际观察结果。</li><li>查询结果更长，是因为 Kubernetes 补充了默认信息和运行状态。</li></ol><h2 id="下一课预告" tabindex="-1"><a class="header-anchor" href="#下一课预告" aria-hidden="true">#</a> 下一课预告</h2><p>下一课只讲 Pod 与容器的区别，并进入容器内部观察进程、文件和网络。等亲眼看到共享关系后，再解释为什么 Kubernetes 不直接调度单个容器。</p>`,125),l=[d];function t(c,r){return a(),n("div",null,l)}const p=e(i,[["render",t],["__file","04-第三课-看懂第一份YAML.html.vue"]]);export{p as default};
